const pgBtn=(k,n)=>{if(n<=PN)return'';const sh=pgN(k,n);return`<div class="pgw">${sh<n?`<button class="hb" onclick="pgMore('${k}',${n})">Detail${tri(0)}</button>`:`<button class="hb" onclick="pgLess('${k}')">Detail${tri(1)}</button>`}</div>`};
const hrow=(i,r,a)=>{const ms=a.H.filter(h=>h[3]==r.k),key='h'+i+'_'+r.k,op=!!OPEN[key];return`<tr><td><a onclick="go('/t/${r.k}')">${esc(r.n)}</a></td><td>${r.tier?tierB(r.tier):'<span class="mu">–</span>'}</td><td>${r.fin?bd(r.lab,pc(r.lab)):'<span class="mu">Masih bertanding</span>'}</td><td style="text-align:right">${dtl(key,op)}</td></tr>`+(op?`<tr><td colspan="4" style="padding:8px">${ms.length?`<div class="wrap"><table><tr><th>Babak</th><th>Lawan</th><th>Skor</th><th>Hasil</th></tr>${ms.map(([n,r2,x])=>{const k=x.a==i?0:1;return`<tr><td>${r2}</td><td>${tm(x.a==i?x.b:x.a,18)}</td><td>${x.s[k]} : ${x.s[1-k]}</td><td>${x.w==i?bd('Menang','ok'):bd('Kalah','live')}</td></tr>`}).join('')}</table></div>`:'<p class="mu" style="margin:0">Belum ada pertandingan selesai.</p>'}</td></tr>`:'')};
function histRows(i){const a=tst(i);if(!a.TR.length)return'';const k='phi'+i;return`<div class="wrap card" style="padding:0"><table><tr><th>Pertandingan</th><th>Tier</th><th>Posisi</th><th></th></tr>${srtd('sr2_'+i,a.TR,r=>r.tier,r=>r.lab).slice(0,pgN(k,a.TR.length)).map(r=>hrow(i,r,a)).join('')}</table></div>${pgBtn(k,a.TR.length)}`}
function stand(k){const k0=CUR;setCur(k);const rows=places().map(p=>[p[0],p[1].slice()]);if(X.cm!=null&&rows[1]&&rows[1][1][0]==X.cm&&rows[0][1][0]!=X.cm){const t=rows[0][1];rows[0][1]=rows[1][1];rows[1][1]=t}const out=rows.map(p=>[p[0],p[1],X.prize*pp(p[0])/100]);setCur(k0);return out}
function orgHist(D){const ids=D.map(d=>d[1]),oid=D[0]?D[0][0].o:'',M={};D.forEach(([t,i])=>tst(i).TR.forEach(r=>{(M[r.k]=M[r.k]||{k:r.k,n:r.n,d:[]}).d.push([i,r])}));const L=Object.values(M).sort((a,b)=>a.k-b.k);if(!L.length)return'<p class="mu">Belum bertanding.</p>';
const pk='poh'+oid,multi=true,nc=5;return`<div class="wrap card" style="padding:0"><table><tr><th>Pertandingan</th><th>Tier</th>${multi?'<th>Tim</th>':''}<th>Posisi</th><th></th></tr>${srtd('sr3_'+oid,L,e=>S.tours[e.k]&&S.tours[e.k].tier,e=>e.d.map(x=>x[1].lab).sort((a,b)=>plk(a)-plk(b))[0]).slice(0,pgN(pk,L.length)).map(e=>{const key='oh'+oid+'_'+e.k,op=!!OPEN[key],n=e.d.length,tr=S.tours[e.k]&&S.tours[e.k].tier;
return e.d.map(([i,r],j)=>`<tr>${j==0?`<td rowspan="${n}"><a onclick="go('/t/${e.k}')">${esc(e.n)}</a></td><td rowspan="${n}">${tr?tierB(tr):'<span class="mu">–</span>'}</td>`:''}${multi?`<td>${esc(S.teams[i].n)}</td>`:''}<td>${r.fin?bd(r.lab,pc(r.lab)):'<span class="mu">Masih bertanding</span>'}</td>${j==0?`<td rowspan="${n}" style="text-align:right">${dtl(key,op)}</td>`:''}</tr>`).join('')+(op?`<tr><td colspan="${nc}" style="padding:8px"><div class="wrap"><table><tr><th>Posisi</th><th>Tim</th><th>Hadiah</th></tr>${stand(e.k).map(([l,a,h])=>`<tr><td>${bd(l,pc(l))}</td><td>${a.map(i=>ids.includes(i)?`<span class="mine">${tm(i,18)}</span>`:tm(i,18)).join(' &nbsp; ')}</td><td>${fmt(h)}${a.length>1?' <span class="mu">(per tim)</span>':''}</td></tr>`).join('')}</table></div></td></tr>`:'')}).join('')}</table></div>${pgBtn(pk,L.length)}`}

function org(id){const k=orgK(id),o=S.orgs[k];if(!o)return'<div class="card">Tim tidak ditemukan.</div>';const D=S.teams.map((t,i)=>[t,i]).filter(([t])=>t.o==o.id);let ch=0,earn=0;D.forEach(([t,i])=>{const a=tst(i);ch+=a.champs;earn+=a.earn});const A=oact(D.map(d=>d[1]));
 return`<div class="crumb">Beranda › Tim › ${esc(o.n)}</div><div class="layout"><div><h1>${esc(o.n)}</h1>${o.c?`<div class="mu">${flag(o.c)} ${esc(o.c)}</div>`:''}${o.desc?`<div class="card" style="margin-top:12px">${esc(o.desc)}</div>`:''}
<h2>Divisi</h2>${D.length?`<div class="grid">${D.map(([t,i])=>`<div class="tile" onclick="go('/team/${i}')">${lg(i,64)}<b>${esc(t.n)}</b><span class="mu">${flag(t.c)} ${esc(t.c)}${gname(t.g)?' · '+esc(gname(t.g)):''}</span><span class="mu">${tst(i).champs} juara · ${fmt(tst(i).earn)}</span></div>`).join('')}</div>`:'<p class="mu">Belum ada divisi.</p>'}
<h2>Sedang Bertanding / Berikutnya</h2>${A.N.length?`<div class="wrap"><table><tr><th>Pertandingan</th><th>Babak</th><th>Divisi</th><th>Lawan</th><th>Jadwal</th></tr>${A.N.map(([n,r,x,me,d])=>`<tr><td>${esc(n)}</td><td>${r}</td><td>${esc(S.teams[me].n)}${gname(S.teams[me].g)?' <span class="mu">('+esc(gname(S.teams[me].g))+')</span>':''}</td><td>${tm(x.a,18)} <span class="mu">vs</span> ${tm(x.b,18)}</td><td>${esc(d||'')}</td></tr>`).join('')}</table></div>`:'<p class="mu">Tidak ada pertandingan berlangsung atau terjadwal.</p>'}
<h2 class="h2s">Riwayat Pertandingan${srtBtn('sr3_'+(D[0]?D[0][0].o:''),new Set(D.flatMap(([t,i])=>tst(i).TR.map(r=>r.k))).size)}</h2>${orgHist(D)}</div>
<div class="ibx"><div class="t">${esc(o.n)}</div><div class="lgo">${olg(k,110)}</div><dl>${o.t?`<dt>Tag</dt><dd>${esc(o.t)}</dd>`:''}${o.c?`<dt>Negara</dt><dd>${flag(o.c)} ${esc(o.c)}</dd>`:''}<dt>Divisi</dt><dd>${D.length}</dd><dt>Juara</dt><dd>${trophy('tco'+k,ch)}</dd><dt>Total hadiah</dt><dd>${fmt(earn)}</dd></dl></div></div>`}
function team(i){const t=S.teams[i];if(!t)return'<div class="card">Tim tidak ditemukan.</div>';const{s,H,TR,earn,champs}=tst(i),ok=orgK(t.o),oo=S.orgs[ok],ol=oo?`<a onclick="go('/org/${encodeURIComponent(oo.id)}')">${esc(oo.n)}</a>`:'',sib=oo?S.teams.map((x,k)=>[x,k]).filter(([x,k])=>k!=i&&x.o==oo.id):[];
 return`<div class="crumb">Beranda › Tim › ${esc(t.n)}</div><div class="layout"><div><h1>${esc(t.n)}</h1><div class="mu">${flag(t.c)}${gname(t.g)?' '+esc(gname(t.g)):''}${ol?' · Divisi dari '+ol:''}</div>
<div class="card" style="margin-top:12px"><b>${esc(t.n)}</b> (${esc(t.t)}) adalah tim esports${gname(t.g)?' '+esc(gname(t.g)):''} asal ${esc(t.c)}${ol?', salah satu divisi dari <b>'+ol+'</b>':''}. ${TR.length?'Mengikuti '+TR.length+' pertandingan di situs ini.':'Belum mengikuti pertandingan.'}${sib.length?'<div style="margin-top:8px">Divisi lain: '+sib.map(([x,k])=>`<a onclick="go('/team/${k}')">${esc(x.n)}</a>${gname(x.g)?' <span class="mu">('+esc(gname(x.g))+')</span>':''}`).join(', ')+'</div>':''}</div>
<h2 class="h2s">Hasil Pertandingan${srtBtn('sr1_'+i,TR.length)}</h2>${TR.length?`<div class="wrap"><table><tr><th>Pertandingan</th><th>Tier</th><th>Posisi</th><th>Hadiah</th></tr>${srtd('sr1_'+i,TR,r=>r.tier,r=>r.lab).slice(0,pgN('ptr'+i,TR.length)).map(r=>`<tr><td><a onclick="go('/t/${r.k}')">${esc(r.n)}</a></td><td>${r.tier?tierB(r.tier):'<span class="mu">–</span>'}</td><td>${r.fin?bd(r.lab,pc(r.lab)):'<span class="mu">Masih bertanding</span>'}</td><td>${r.fin?fmt(r.pr):'–'}</td></tr>`).join('')}</table></div>${pgBtn('ptr'+i,TR.length)}`:'<p class="mu">Belum ada.</p>'}
${histRows(i)?`<h2 class="h2s">Riwayat Pertandingan${srtBtn('sr2_'+i,tst(i).TR.length)}</h2>${histRows(i)}`:''}
<h2>Roster</h2><div class="wrap"><table><tr><th>#</th><th>ID Pemain</th><th>Peran</th></tr>${t.r.map((p,k)=>`<tr><td>${k+1}</td><td>${esc(p[0]||'TBD')}</td><td>${esc(p[1])}</td></tr>`).join('')}</table></div>
${t.a.length?`<h2>Pencapaian Sebelumnya</h2><div class="wrap"><table><tr><th>Tahun</th><th>Posisi</th><th>Pertandingan</th><th>Hadiah</th></tr>${t.a.map(a=>`<tr><td>${esc(a[0])}</td><td>${bd(esc(a[1]),pc(a[1]))}</td><td>${esc(a[2])}</td><td>${fmt(a[3])}</td></tr>`).join('')}</table></div>`:''}</div>
<div class="ibx"><div class="t">${esc(t.n)}</div><div class="lgo">${lg(i,110)}</div><dl>${gname(t.g)?`<dt>Game</dt><dd>${esc(gname(t.g))}</dd>`:''}${ol?`<dt>Tim</dt><dd>${ol}</dd>`:''}<dt>Tag</dt><dd>${esc(t.t)}</dd><dt>Negara</dt><dd>${flag(t.c)} ${esc(t.c)}</dd><dt>Juara</dt><dd>${trophy('tct'+i,champs)}</dd><dt>Total hadiah</dt><dd>${fmt(earn)}</dd><dt>Win rate</dt><dd>${s.wr}%</dd></dl></div></div>`}
