 if(!ADMIN)return`<div class="card" style="max-width:380px;margin:30px auto"><h1 style="font-size:22px">Login Admin</h1><p class="mu">Khusus pengelola situs.</p><input type="password" id="pw" placeholder="Password" style="width:100%;padding:8px 10px;border:1px solid var(--bd);border-radius:6px;background:var(--card);color:var(--tx);min-height:40px" onkeydown="if(event.key=='Enter')login()"><p><button onclick="login()">Masuk</button></p></div>`;
 if(EI>=S.tours.length)EI=0;setCur(EI);const tabs=[['tr','Pertandingan'],['pt','Peserta'],['tm','Tim & Pemain'],['og','Tim Pusat'],['bk','Skor'],['hs','Riwayat'],['gm','Game'],['ak','Akun Peserta'],['dt','Data']],t=X;let b='';
